supplemental_checks.decoded_command_payload:
$ProgressPreference = 'SilentlyContinue'
$files = @('WinPDFMerge.ps1', 'src/WinPDFMerge.Helpers.ps1', 'tools/test/Invoke-Tests.ps1', 'tests/unit/Dependencies.Tests.ps1', 'tests/dependencies/Dependencies.Entry.Tests.ps1')
foreach ($file in $files) {
 $tokens = $null
 $errors = $null
 [void][System.Management.Automation.Language.Parser]::ParseFile((Join-Path $PWD $file), [ref]$tokens, [ref]$errors)
 if ($errors.Count -ne 0) { $errors | Format-List; exit 1 }
}
Write-Output ('Parser PASS: 5 files; actual shell ' + $PSVersionTable.PSVersion)
